@prefix ex: <http://example.org/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix wdt: <http://www.wikidata.org/prop/dataset/> .
@prefix wdt: <http://www.wikidata.org/prop/> .
@prefix wikibase: <http://www.wikidata.org/ontology/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

SELECT ?entity ?label ?lat ?lon 
WHERE {
  ?entity a wikibase:Entity ;
    wdt:entityId "{?entity}" ;
    wdt:label "{?label}" .

  wdt:entityLatitude ?lat ;
    wdt:entityLongitude ?lon ;
    wdt:entity "?entity" .

  FILTER (
    (ex:city_qid = ?entity) ||
    (ex:country_qid = ?entity)
  )
}

